/**
 * A published article.
 */
final class Post
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly DateTimeImmutable $createdAt,
        private readonly DateTimeImmutable $updatedAt,
        private readonly ?int $postId,
        private readonly string $slug,
        private readonly string $title,
        private readonly ?Money $price,
        private readonly PostStatus $status,
        private readonly PostVisibility $visibility,
        private readonly ?DateTimeImmutable $publishedAt,
    ) {
    }

    public function getId(): EntityId
    {
        return $this->id;
    }

    /**
     * When the row was first written. Filled by the framework.
     */
    public function getCreatedAt(): DateTimeImmutable
    {
        return $this->createdAt;
    }

    /**
     * When the row was last written. Filled by the framework.
     */
    public function getUpdatedAt(): DateTimeImmutable
    {
        return $this->updatedAt;
    }

    public function getPostId(): ?int
    {
        return $this->postId;
    }

    /**
     * Write-once, and chosen by whoever creates the post.
     */
    public function getSlug(): string
    {
        return $this->slug;
    }

    public function getTitle(): string
    {
        return $this->title;
    }

    public function getPrice(): ?Money
    {
        return $this->price;
    }

    public function getStatus(): PostStatus
    {
        return $this->status;
    }

    public function getVisibility(): PostVisibility
    {
        return $this->visibility;
    }

    /**
     * When it went live. A plain datetime, set by whoever publishes it.
     */
    public function getPublishedAt(): ?DateTimeImmutable
    {
        return $this->publishedAt;
    }

    /**
     * @return EntityQuery<Comment>
     */
    public function comments(): EntityQuery
    {
        /** @var EntityQuery<Comment> $related */
        $related = $this->edges->toMany('Post', $this->id, 'comments');

        return $related;
    }

    /**
     * @return EntityQuery<Tag>
     */
    public function tags(): EntityQuery
    {
        /** @var EntityQuery<Tag> $related */
        $related = $this->edges->toMany('Post', $this->id, 'tags');

        return $related;
    }

    public static function of(
        EntityId $id,
        EdgeLoader $edges,
        DateTimeImmutable $createdAt,
        DateTimeImmutable $updatedAt,
        ?int $postId,
        string $slug,
        string $title,
        ?Money $price,
        PostStatus $status,
        PostVisibility $visibility,
        ?DateTimeImmutable $publishedAt,
    ): self {
        return new self($id, $edges, $createdAt, $updatedAt, $postId, $slug, $title, $price, $status, $visibility, $publishedAt);
    }
}

