namespace App\Elephentity\Post;

use App\Elephentity\Post\Contract\PostAuditTrigger;
use App\Elephentity\Post\Contract\PostReindexTrigger;
use Eleph\Runtime\Mutation\EntityTriggers;
use Eleph\Runtime\Mutation\MutationContext;
use Eleph\Runtime\Trigger\TriggerEvent;
use Eleph\Runtime\Trigger\TriggerPhase;

/**
 * Runs Post's triggers, in the order the spec declares them.
 */
final readonly class PostTriggers implements EntityTriggers
{
    public function __construct(
        private PostAuditTrigger $auditTrigger,
        private PostReindexTrigger $reindexTrigger,
    ) {
    }

    public function dispatch(TriggerPhase $phase, TriggerEvent $event, MutationContext $context): void
    {
        $typed = PostMutationContext::of($context);

        if (TriggerPhase::PostCommit === $phase && in_array($event, [TriggerEvent::Create, TriggerEvent::Update], true)) {
            $this->auditTrigger->handle($typed);
        }

        if (TriggerPhase::PostCommit === $phase && in_array($event, [TriggerEvent::Create, TriggerEvent::Update], true)) {
            $this->reindexTrigger->handle($typed);
        }
    }
}

